# Let me search for the tool calls to see the sequence of edits
idx = await CONTEXT.search("[tool ")
items = idx['items']
for item in items:
    ofs = item['offset']
    snippet = item['snippet']
    if 'edit_file' in snippet or 'shell' in snippet or 'read_file' in snippet:
        text = await CONTEXT.read(max(0, ofs-3), 200)
        if 'edit_file' in text or 'shell' in text.split(']')[-1][:20] if ']' in text else '':
        print(f"  {snippet[:150]}")
